<template><div class="page-view"><div class="welcome-row"><div><p class="eyebrow">ADMINISTRADOR</p><h1>Olá, Kayque 👋</h1><p class="subcopy">Aqui está o panorama dos projetos da sua equipe.</p></div><button class="primary-btn" @click="$emit('task')"><Plus/>Nova tarefa</button></div><div class="metrics"><button v-for="item in metrics" :key="item.label" class="metric-card" @click="$emit('navigate',item.path)"><span :class="['metric-icon',item.color]"><component :is="item.icon"/></span><span><p>{{item.label}}</p><strong>{{item.value}}</strong><small :class="item.color">Abrir tarefas</small></span><span class="metric-arrow">→</span></button></div><div class="dashboard-grid"><section class="panel tasks-panel"><div class="panel-head"><div><h2>Tarefas recentes</h2><p>Acompanhe o que precisa da sua atenção.</p></div><button class="text-btn" @click="$emit('navigate','/tarefas')">Ver todas →</button></div><div class="table-wrap"><table><thead><tr><th>TAREFA</th><th>RESPONSÁVEL</th><th>PRIORIDADE</th><th>PRAZO</th><th>STATUS</th></tr></thead><tbody><tr v-for="task in tasks.slice(0,5)" :key="task.id" class="click-row" @click="$emit('task',task)"><td><div class="task-title"><span class="avatar">?</span><div><strong>{{task.title}}</strong><small>{{project(task.projectId)}}</small></div></div></td><td><div class="assignee-info"><strong>Equipe</strong><small>Função não informada</small></div></td><td><span :class="['priority',priorityClass(task.priority)]"><i/>{{task.priority}}</span></td><td>{{fmt(task.due)}}</td><td><span :class="['status',statusClass(task.status)]">{{task.status}}</span></td></tr></tbody></table></div></section><aside class="right-column"><section class="panel"><div class="panel-head compact"><div><h2>Progresso das tarefas</h2><p>Clique para explorar</p></div></div><div class="donut-wrap"><button class="donut donut-button" :style="donutStyle" @click="$emit('navigate','/tarefas?status=concluida')"><div><strong>{{percent}}%</strong><span>concluído</span></div></button><div class="legend interactive"><button v-for="row in progress" :key="row.label" @click="$emit('navigate',row.path)"><i :class="['dot',row.dot]"/>{{row.label}}<strong>{{row.value}}</strong></button></div></div></section><section class="panel"><div class="panel-head compact"><div><h2>Atividade recente</h2><p>Atualizações do workspace</p></div></div><div class="activity"><span class="avatar">?</span><p><strong>Dados sincronizados</strong><br/><span>Projetos, tarefas e calendário</span><small>Agora</small></p></div></section><section v-if="weekly" class="panel weekly-card"><strong>Resumo semanal</strong><p>{{counts.done}} concluídas · {{counts.active}} em andamento · {{counts.pending}} pendentes</p></section></aside></div></div></template>
<script setup lang="ts">import{computed}from"vue";import{Check,Clock3,Plus}from"lucide-vue-next";import type{Project,Task}from"../stores/taskflow";const props=defineProps<{tasks:Task[];projects:Project[];counts:{all:number;pending:number;active:number;done:number};weekly:boolean}>();defineEmits(["navigate","task"]);const metrics=computed(()=>[{label:"Todas as tarefas",value:props.counts.all,color:"purple",icon:Check,path:"/tarefas"},{label:"Tarefas pendentes",value:props.counts.pending,color:"blue",icon:Clock3,path:"/tarefas?status=pendente"},{label:"Em andamento",value:props.counts.active,color:"orange",icon:Clock3,path:"/tarefas?status=andamento"},{label:"Concluídas",value:props.counts.done,color:"green",icon:Check,path:"/tarefas?status=concluida"}]),percent=computed(()=>props.counts.all?Math.round(props.counts.done/props.counts.all*100):0),donutStyle=computed(()=>({background:`conic-gradient(#6c5ce7 0 ${percent.value}%,#22b8a0 ${percent.value}% 70%,#ebeafd 0)`})),progress=computed(()=>[{label:"Concluída",value:props.counts.done,dot:"purple",path:"/tarefas?status=concluida"},{label:"Em andamento",value:props.counts.active,dot:"teal",path:"/tarefas?status=andamento"},{label:"Pendente",value:props.counts.pending,dot:"pale",path:"/tarefas?status=pendente"}]);const project=(id:number)=>props.projects.find(p=>p.id===id)?.name||"—",fmt=(v:string)=>new Intl.DateTimeFormat("pt-BR",{day:"2-digit",month:"short"}).format(new Date(v+"T12:00:00")),statusClass=(s:string)=>s==="Concluída"?"green":s==="Em andamento"?"blue":s==="Atrasada"?"red":"gray",priorityClass=(p:string)=>p==="Alta"?"high":p==="Média"?"medium":"low";</script>
